 84	import { test, expect } from './support/fixtures';
 85	import { expectPrice } from './support/assertions';
 86	import { PRODUCTS } from './support/test-data';
 87	
 88	test('TC-03: Change the quantity and remove a product in the basket', async ({
 89	  customer,
 90	  page,
 91	  loginPage,
 92	  basket,
 93	  navBar,
 94	}) => {
 95	  const a = PRODUCTS.raspberryJuice;
 96	  const b = PRODUCTS.eggfruitJuice;
 97	  await customer.api.addToBasket(a.name, 1);
 98	  await customer.api.addToBasket(b.name, 1);
 99	  await loginPage.login(customer.email, customer.password);
100	
101	  await test.step('1. Open the basket', async () => {
102	    await basket.open();
103	    await expect(basket.rows).toHaveCount(2);
104	    await expect(basket.quantity(a.name)).toHaveText('1');
105	    await expect(basket.quantity(b.name)).toHaveText('1');
106	    await expectPrice(basket.totalPrice, a.price + b.price);
107	    await expect(navBar.basketCounter).toHaveText('2');
108	  });
109	
110	  await test.step('2. Click plus in the row of product A', async () => {
111	    await basket.increase(a.name);
112	    await expect(basket.quantity(a.name)).toHaveText('2');
113	    await expectPrice(basket.totalPrice, 2 * a.price + b.price);
114	    await expect(navBar.basketCounter).toHaveText('3');
115	  });
116	
117	  await test.step('3. Click minus in the row of product A', async () => {
118	    await basket.decrease(a.name);
119	    await expect(basket.quantity(a.name)).toHaveText('1');
120	    await expectPrice(basket.totalPrice, a.price + b.price);
121	    await expect(navBar.basketCounter).toHaveText('2');
122	  });
123	
124	  await test.step('4. Click minus in the row of product A again', async () => {
125	    await basket.decrease(a.name);
126	    await expect(basket.row(a.name)).toBeVisible();
127	    await expect(basket.quantity(a.name)).toHaveText('1');
128	    await expectPrice(basket.totalPrice, a.price + b.price);
129	    // The quantity must stay 1 also after a reload from the server.
130	    await page.reload();
131	    await basket.waitForLoad();
132	    await expect(basket.row(a.name)).toBeVisible();
133	    await expect(basket.quantity(a.name)).toHaveText('1');
134	    await expectPrice(basket.totalPrice, a.price + b.price);
135	  });
136	
137	  await test.step('5. Click trash in the row of product A', async () => {
138	    await basket.remove(a.name);
139	    await expect(basket.row(a.name)).toHaveCount(0);
140	    await expect(basket.rows).toHaveCount(1);
141	    await expect(basket.quantity(b.name)).toHaveText('1');
142	    await expectPrice(basket.totalPrice, b.price);
143	    await expect(navBar.basketCounter).toHaveText('1');
144	  });
145	});
