148	import { test, expect } from './support/fixtures';
149	import { expectPrice } from './support/assertions';
150	import { APPLE_JUICE_LIMIT, PRODUCTS } from './support/test-data';
151	
152	test('TC-04: Purchase limit for one product', async ({ loggedInCustomer: _, page, productList, basket, navBar }) => {
153	  const product = PRODUCTS.appleJuice;
154	  const limitMessage = `You can order only up to ${APPLE_JUICE_LIMIT} items of this product.`;
155	
156	  await test.step('1. Add the product from the product list', async () => {
157	    await productList.open();
158	    await productList.addToBasket(product.name);
159	    await expect(productList.message(`Placed ${product.name} into basket.`).first()).toBeVisible();
160	    await expect(navBar.basketCounter).toHaveText('1');
161	  });
162	
163	  await test.step(`2. Click plus until the quantity is ${APPLE_JUICE_LIMIT}`, async () => {
164	    await basket.open();
165	    for (let quantity = 2; quantity <= APPLE_JUICE_LIMIT; quantity++) {
166	      await basket.increase(product.name);
167	      await expect(basket.quantity(product.name)).toHaveText(String(quantity));
168	    }
169	    await expect(basket.quantity(product.name)).toHaveText(String(APPLE_JUICE_LIMIT));
170	    await expectPrice(basket.totalPrice, APPLE_JUICE_LIMIT * product.price);
171	    await expect(basket.message(limitMessage)).toHaveCount(0);
172	  });
173	
174	  await test.step('3. Click plus one more time', async () => {
175	    await basket.increase(product.name);
176	    await expect(basket.message(limitMessage).first()).toBeVisible();
177	  });
178	
179	  await test.step('4. Read the basket', async () => {
180	    await expect(basket.quantity(product.name)).toHaveText(String(APPLE_JUICE_LIMIT));
181	    await expectPrice(basket.totalPrice, APPLE_JUICE_LIMIT * product.price);
182	    await expect(navBar.basketCounter).toHaveText(String(APPLE_JUICE_LIMIT));
183	    // The server must keep the limit too.
184	    await page.reload();
185	    await basket.waitForLoad();
186	    await expect(basket.quantity(product.name)).toHaveText(String(APPLE_JUICE_LIMIT));
187	    await expectPrice(basket.totalPrice, APPLE_JUICE_LIMIT * product.price);
188	  });
189	
190	  await test.step('5. Add the product again from the product list', async () => {
191	    await productList.open();
192	    await productList.addToBasket(product.name);
193	    await expect(productList.message(limitMessage).first()).toBeVisible();
194	    await expect(navBar.basketCounter).toHaveText(String(APPLE_JUICE_LIMIT));
195	  });
196	});
