199	import { test, expect } from './support/fixtures';
200	import { expectPrice } from './support/assertions';
201	import { addSavedAddressAndCard } from './support/checkout';
202	import { ADDRESS, CARD_LAST_DIGITS, DELIVERY, PRODUCTS, couponCode, money, priceText } from './support/test-data';
203	
204	test('TC-05: Valid coupon on the payment step', async ({
205	  customer,
206	  loginPage,
207	  basket,
208	  selectAddress,
209	  deliveryMethod,
210	  payment,
211	  orderSummary,
212	}) => {
213	  const product = PRODUCTS.eggfruitJuice;
214	  const quantity = 2;
215	  const discountPercent = 10;
216	  const coupon = couponCode(discountPercent);
217	
218	  await addSavedAddressAndCard(customer);
219	  await customer.api.addToBasket(product.name, quantity);
220	  await loginPage.login(customer.email, customer.password);
221	
222	  const items = money(product.price * quantity);
223	  const promotion = money((items * discountPercent) / 100);
224	  const total = money(items + DELIVERY.oneDay.price - promotion);
225	
226	  await test.step('1. Open the basket and click Checkout', async () => {
227	    await basket.open();
228	    await basket.checkout();
229	    await expect(selectAddress.title).toBeVisible();
230	    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.fullName);
231	    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.streetAddress);
232	    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.country);
233	  });
234	
235	  await test.step('2. Select the saved address and continue', async () => {
236	    await selectAddress.selectSavedAddressAndContinue();
237	    await expect(deliveryMethod.title).toBeVisible();
238	    for (const option of [DELIVERY.oneDay, DELIVERY.fast, DELIVERY.standard]) {
239	      await expect(deliveryMethod.option(option.name)).toBeVisible();
240	      await expect(deliveryMethod.optionPrice(option.name)).toHaveText(priceText(option.price));
241	    }
242	  });
243	
244	  await test.step('3. Select One Day Delivery and continue', async () => {
245	    await deliveryMethod.selectAndContinue(DELIVERY.oneDay.name);
246	    await expect(payment.title).toBeVisible();
247	    await expect(payment.savedCardRow).toContainText(CARD_LAST_DIGITS);
248	    await expect(payment.couponPanelButton).toBeVisible();
249	  });
250	
251	  await test.step('4. Redeem the coupon of the current month', async () => {
252	    await payment.openCouponPanel();
253	    await payment.redeemCoupon(coupon);
254	    await expect(payment.couponConfirmation).toHaveText(
255	      `Your discount of ${discountPercent}% will be applied during checkout.`,
256	    );
257	    await expect(payment.couponError).toHaveCount(0);
