335	import { test, expect } from './support/fixtures';
336	import { expectPrice } from './support/assertions';
337	import { addSavedAddressAndCard } from './support/checkout';
338	import { ADDRESS, CARD, CARD_LAST_DIGITS, DELIVERY, PRODUCTS, couponCode, itemsTotal, money } from './support/test-data';
339	
340	test('TC-07: Order with a card, from basket to order history', async ({
341	  loggedInCustomer,
342	  page,
343	  productList,
344	  navBar,
345	  basket,
346	  selectAddress,
347	  deliveryMethod,
348	  payment,
349	  orderSummary,
