351	  orderHistory,
352	}) => {
353	  const a = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
354	  const b = { product: PRODUCTS.carrotJuice, quantity: 1 };
355	  const discountPercent = 10;
356	  const coupon = couponCode(discountPercent);
357	
358	  await addSavedAddressAndCard(loggedInCustomer);
359	
360	  const items = itemsTotal([a, b]);
361	  const promotion = money((items * discountPercent) / 100);
362	  const total = money(items + DELIVERY.oneDay.price - promotion);
363	  let orderId = '';
364	
365	  await test.step('1. Add product A two times and product B one time', async () => {
366	    await productList.open();
367	    await productList.addToBasket(a.product.name);
368	    await expect(navBar.basketCounter).toHaveText('1');
369	    await productList.addToBasket(a.product.name);
370	    await expect(navBar.basketCounter).toHaveText('2');
371	    await productList.addToBasket(b.product.name);
372	    await expect(navBar.basketCounter).toHaveText(String(a.quantity + b.quantity));
373	  });
374	
375	  await test.step('2. Open the basket', async () => {
376	    await basket.open();
377	    await expect(basket.rows).toHaveCount(2);
378	    await expect(basket.quantity(a.product.name)).toHaveText(String(a.quantity));
379	    await expect(basket.quantity(b.product.name)).toHaveText(String(b.quantity));
380	    await expectPrice(basket.totalPrice, items);
381	  });
382	
383	  await test.step('3. Checkout with the saved address', async () => {
384	    await basket.checkout();
385	    await selectAddress.selectSavedAddressAndContinue();
386	    await expect(deliveryMethod.title).toBeVisible();
387	  });
388	
389	  await test.step('4. Select One Day Delivery and continue', async () => {
390	    await deliveryMethod.selectAndContinue(DELIVERY.oneDay.name);
391	    await expect(payment.title).toBeVisible();
392	  });
393	
394	  await test.step('5. Redeem the coupon of the current month', async () => {
395	    await payment.openCouponPanel();
396	    await payment.redeemCoupon(coupon);
397	    await expect(payment.couponConfirmation).toHaveText(
398	      `Your discount of ${discountPercent}% will be applied during checkout.`,
399	    );
400	  });
401	
402	  await test.step('6. Select the saved card and continue to the order summary', async () => {
403	    await payment.selectSavedCardAndContinue();
404	    await orderSummary.waitForLoad();
405	    await expect(orderSummary.deliveryAddress).toContainText(ADDRESS.fullName);
406	    await expect(orderSummary.deliveryAddress).toContainText(
407	      `${ADDRESS.streetAddress}, ${ADDRESS.city}, ${ADDRESS.state}, ${ADDRESS.zipCode}`,
408	    );
409	    await expect(orderSummary.deliveryAddress).toContainText(ADDRESS.country);
410	    await expect(orderSummary.paymentMethod).toContainText(`Card ending in ${CARD_LAST_DIGITS}`);
411	    await expect(orderSummary.paymentMethod).toContainText(CARD.fullName);
412	    await expect(orderSummary.basketRows).toHaveCount(2);
413	    await expect(orderSummary.row(a.product.name)).toContainText(String(a.quantity));
414	    await expect(orderSummary.row(b.product.name)).toContainText(String(b.quantity));
