462	import { DELIVERY, PRODUCTS, bonusPoints, money, priceText } from './support/test-data';
463	
464	test('TC-08: Payment with the wallet', async ({
465	  customer,
466	  loginPage,
467	  page,
468	  navBar,
469	  basket,
470	  selectAddress,
471	  deliveryMethod,
472	  payment,
