480	  const topUp = 3.99;
481	  const total = money(line.product.price * line.quantity + DELIVERY.standard.price);
482	  const bonus = bonusPoints([line]);
483	
484	  const cardId = await addSavedAddressAndCard(customer);
485	  await customer.api.addToBasket(line.product.name, line.quantity);
486	  expect(await customer.api.topUpWallet(firstBalance, cardId)).toBe(firstBalance);
487	  await loginPage.login(customer.email, customer.password);
488	
489	  // Part 1: the wallet holds less than the order total.
490	
491	  await test.step('1. Checkout with the saved address', async () => {
492	    await basket.open();
493	    await basket.checkout();
494	    await selectAddress.selectSavedAddressAndContinue();
495	    await expect(deliveryMethod.title).toBeVisible();
496	  });
497	
