500	    await expect(payment.title).toBeVisible();
501	    await expectPrice(payment.walletBalance, firstBalance);
502	    await expect(payment.walletPayButton).toHaveText(new RegExp(`Pay ${priceText(total)}`));
503	  });
504	
505	  await test.step(`3. The button Pay ${priceText(total)} is disabled`, async () => {
506	    await expect(payment.walletPayButton).toBeDisabled();
