import { expect, Locator } from '@playwright/test';
import { money, parsePrice } from './test-data';

/**
 * Waits until the price in the element equals the expected amount.
 * The shop shows some totals without trailing zeros (`0¤`), so the check compares numbers.
 */
export async function expectPrice(locator: Locator, expected: number, message?: string): Promise<void> {
  await expect
    .poll(
      async () => {
        const text = await locator.innerText();
        // The page can show an empty value while it loads data; poll again in that case.
        return /\d/.test(text) ? parsePrice(text) : text;
      },
      { message },
    )
    .toBe(money(expected));
}

