import * as z85 from 'z85';

export type Product = { name: string; price: number };

/** Products and prices from the shop catalog of Juice Shop v20.3.0 (normal customer prices). */
export const PRODUCTS = {
  appleJuice: { name: 'Apple Juice (1000ml)', price: 1.99 },
  carrotJuice: { name: 'Carrot Juice (1000ml)', price: 2.99 },
  eggfruitJuice: { name: 'Eggfruit Juice (500ml)', price: 8.99 },
  raspberryJuice: { name: 'Raspberry Juice (1000ml)', price: 4.99 },
} satisfies Record<string, Product>;

export const DELIVERY = {
  oneDay: { name: 'One Day Delivery', price: 0.99 },
  fast: { name: 'Fast Delivery', price: 0.5 },
  standard: { name: 'Standard Delivery', price: 0 },
} as const;

/** Basket limit of Apple Juice (1000ml) for a normal customer. */
export const APPLE_JUICE_LIMIT = 5;

export const ADDRESS = {
  country: 'Ukraine',
  fullName: 'Test Customer',
  mobileNum: '501234567',
  zipCode: '01001',
  streetAddress: '1 Khreshchatyk Street',
  city: 'Kyiv',
  state: 'Kyiv',
} as const;

export const CARD = {
  fullName: 'Test Customer',
  cardNum: '4111111111111111',
  expMonth: '12',
  expYear: '2090',
} as const;

export const CARD_LAST_DIGITS = CARD.cardNum.slice(-4);

/** Unique email for a new customer account. */
export function uniqueEmail(prefix: string): string {
  const unique = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  return `${prefix}-${unique}@example.test`;
}

/** Rounds an amount to cents, the way the shop shows prices. */
export function money(amount: number): number {
  return Math.round(amount * 100) / 100;
}

/** Price text as the shop shows it with two decimals, for example `8.99¤`. */
export function priceText(amount: number): string {
  return `${money(amount).toFixed(2)}¤`;
}

/** Parses a number from a text like `Total Price: 8.99¤`. */
export function parsePrice(text: string): number {
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) throw new Error(`No price in text: "${text}"`);
  return Number(match[0]);
}

/** Bonus points of one product: price / 10, rounded to a whole number, × quantity. */
export function bonusPoints(items: { product: Product; quantity: number }[]): number {
  return items.reduce((sum, { product, quantity }) => sum + Math.round(product.price / 10) * quantity, 0);
}

export function itemsTotal(items: { product: Product; quantity: number }[]): number {
  return money(items.reduce((sum, { product, quantity }) => sum + product.price * quantity, 0));
}

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * Coupon code: Z85 encoding of `<MMM><YY>-<NN>`.
 * The shop accepts a coupon only in the month that it names.
 * The tests run on the machine that runs the app, so the local date is the app date.
 */
export function couponCode(percent: number, date: Date = new Date()): string {
  const month = MONTHS[date.getMonth()];
  const year = String(date.getFullYear() % 100).padStart(2, '0');
  const discount = String(percent).padStart(2, '0');
  return z85.encode(`${month}${year}-${discount}`);
}

/** Coupon of the previous month, which the shop must reject as expired. */
export function expiredCouponCode(percent: number, date: Date = new Date()): string {
  return couponCode(percent, new Date(date.getFullYear(), date.getMonth() - 1, 1));
}

